export function debounce(fn, wait = 200, immediate = false) {
  let t;
  return function (...args) {
    const later = () => {
      t = null;
      if (!immediate) fn.apply(this, args);
    };
    const callNow = immediate && !t;
    clearTimeout(t);
    t = setTimeout(later, wait);
    if (callNow) fn.apply(this, args);
  };
}
