public static Dictionary<string, decimal> TotalsByCategory(List<Invoice> invoices)
{
    var result = new Dictionary<string, decimal>();
    foreach (var inv in invoices)
    {
        if (inv.Status == "Void") continue;
        foreach (var line in inv.Lines)
        {
            if (line.Category == null) continue;
            if (!result.ContainsKey(line.Category))
            {
                result[line.Category] = 0m;
            }
            result[line.Category] += line.Quantity * line.UnitPrice;
        }
    }
    var sorted = new Dictionary<string, decimal>();
    foreach (var key in result.Keys.OrderBy(k => k))
    {
        sorted[key] = result[key];
    }
    return sorted;
}
